def _generate_expression(self):
    # turn my _format attribute into the _expression attribute
    # Validate brace matching first
    depth = 0
    i = 0
    while i < len(self._format):
        c = self._format[i]
        if c == '{':
            # Check for escaped '{{'
            if i + 1 < len(self._format) and self._format[i + 1] == '{':
                i += 2
                continue
            depth += 1
        elif c == '}':
            # Check for escaped '}}'
            if i + 1 < len(self._format) and self._format[i + 1] == '}':
                i += 2
                continue
            depth -= 1
            if depth < 0:
                raise ValueError('unmatched closing brace in format')
        i += 1
    if depth > 0:
        raise ValueError('unmatched opening brace in format')

    e = []
    for part in PARSE_RE.split(self._format):
        if not part:
            continue
        elif part == '{{':
            e.append(r'\{')
        elif part == '}}':
            e.append(r'\}')
        elif part[0] == '{':
            # this will be a braces-delimited field to handle
            e.append(self._handle_field(part))
        else:
            # just some text to match
            e.append(REGEX_SAFETY.sub(self._regex_replace, part))
    return ''.join(e)

